package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.os.*;import android.view.*;import java.io.*;import java.util.*;
/** Real receiver and session lifecycle, muted volume; no calls or SMS. */
public final class FmTests extends Instrumentation {
    private boolean keepScan;public void onCreate(Bundle b){keepScan=b!=null&&"true".equals(b.getString("keep-scan"));start();}
    private void check(boolean ok,String text){if(!ok)throw new AssertionError(text);}
    private void waitStarted(){for(int n=0;n<220&&!FmService.playing;n++)SystemClock.sleep(100);check(FmService.playing,"radio start: "+FmService.state);}
    private void waitStopped(){for(int n=0;n<80&&FmService.instance!=null;n++)SystemClock.sleep(100);check(FmService.instance==null&&!FmService.playing,"radio stopped");}
    public void onStart(){final Context c=getTargetContext();Bundle result=new Bundle();SharedPreferences p=c.getSharedPreferences("fm",0);Map<String,?> before=p.getAll();Activity page=null;try{
        check(FmService.instance==null,"FM must be stopped before isolated test");check(FmService.wired(c),"wired antenna connected");p.edit().putInt("frequency",101300).putInt("volume",0).commit();
        page=startActivitySync(new Intent(c,FmActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitStarted();SystemClock.sleep(1000);check(FmService.volume==0,"muted user level applied");
        sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);for(int n=0;n<60&&!FmService.state.startsWith("În redare");n++)SystemClock.sleep(100);check(FmService.frequency==101400,"D-pad tune");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_LEFT);for(int n=0;n<60&&!FmService.state.startsWith("În redare");n++)SystemClock.sleep(100);check(FmService.frequency==101300,"D-pad tune back");
        waitForIdleSync();SystemClock.sleep(250);final Activity radio=page;final java.lang.reflect.Method menu=FmActivity.class.getDeclaredMethod("menu");menu.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{menu.invoke(radio);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();for(int n=0;n<40&&page.hasWindowFocus();n++)SystemClock.sleep(50);check(!page.hasWindowFocus(),"options menu has focus");for(int n=0;n<4;n++)sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();check(p.getStringSet("favorites",Collections.<String>emptySet()).contains("101300"),"favorite saved from menu");
        final FmService service=FmService.instance;runOnMainSync(new Runnable(){public void run(){service.seek(true);}});for(int n=0;n<500&&FmService.seeking;n++)SystemClock.sleep(100);check(FmService.playing&&!FmService.seeking&&FmService.frequency!=101300,"automatic next station: "+FmService.state);result.putString("seek_frequency",""+FmService.frequency);runOnMainSync(new Runnable(){public void run(){service.tune(101300);}});SystemClock.sleep(18000);result.putString("rds_name",FmService.stationName);result.putString("rds_text",FmService.radioText);check(FmService.playing,"RDS polling keeps session active");runOnMainSync(new Runnable(){public void run(){service.setVolume(0);}});SystemClock.sleep(500);check(FmService.playing,"app UID can control FM volume");
        runOnMainSync(new Runnable(){public void run(){service.scan();}});for(int n=0;n<520&&FmService.scanning;n++)SystemClock.sleep(100);check(FmService.playing&&!FmService.scanning&&!FmService.stations.isEmpty(),"scan completed with measured candidates");check(!p.getString("stations","").isEmpty(),"scan results saved");
        runOnMainSync(new Runnable(){public void run(){try{menu.invoke(radio);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();for(int n=0;n<40&&page.hasWindowFocus();n++)SystemClock.sleep(50);check(!page.hasWindowFocus(),"speaker menu has focus");for(int n=0;n<5;n++)sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);for(int n=0;n<70&&!FmService.speaker;n++)SystemClock.sleep(100);check(FmService.speaker&&FmService.playing,"speaker route command accepted");int jack=-1;for(int id:InputDevice.getDeviceIds()){InputDevice d=InputDevice.getDevice(id);if(d!=null&&"msm8909-snd-card Button Jack".equals(d.getName()))jack=id;}check(jack>=0,"codec button device found");final int jackId=jack;runOnMainSync(new Runnable(){public void run(){long now=SystemClock.uptimeMillis();for(int action:new int[]{KeyEvent.ACTION_DOWN,KeyEvent.ACTION_UP})radio.dispatchKeyEvent(new KeyEvent(now,now,action,KeyEvent.KEYCODE_DPAD_CENTER,0,0,jackId,260,0x400,InputDevice.SOURCE_KEYBOARD));}});SystemClock.sleep(8000);check(FmService.speaker&&FmService.playing,"speaker survives codec fallback OK and eight seconds: "+FmService.state);
        runOnMainSync(new Runnable(){public void run(){service.setSpeaker(false);}});for(int n=0;n<70&&FmService.speaker;n++)SystemClock.sleep(100);check(!FmService.speaker&&FmService.playing,"headset route restored");
        Bitmap image=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).takeScreenshot();check(image!=null,"radio screenshot");try(FileOutputStream file=new FileOutputStream(new File(c.getFilesDir(),"fm-test.png"))){image.compress(Bitmap.CompressFormat.PNG,100,file);}finally{image.recycle();}
        runOnMainSync(new Runnable(){public void run(){service.onAudioFocusChange(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);}});waitStopped();check(FmService.state.contains("alt sunet"),"focus loss stop reason");
        runOnMainSync(new Runnable(){public void run(){c.startService(new Intent(c,FmService.class).setAction("start"));}});waitStarted();sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitStopped();
        check(AppCatalog.NAMES.length==28&&AppCatalog.parse("24,23")[25]==25,"old menu order gains FM ID");
        result.putString("result","PASS real FM session from Leo UID, D-pad tuning, favorites, stored scan results, volume, automatic next station, RDS polling and speaker/headset routing, focus-loss stop, restart and OK stop; muted, no calls/SMS");
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{c.stopService(new Intent(c,FmService.class));if(page!=null){final Activity close=page;runOnMainSync(new Runnable(){public void run(){close.finish();}});}String measuredStations=p.getString("stations","");SharedPreferences.Editor edit=p.edit().clear();for(Map.Entry<String,?> item:before.entrySet()){Object v=item.getValue();if(v instanceof Integer)edit.putInt(item.getKey(),(Integer)v);else if(v instanceof String)edit.putString(item.getKey(),(String)v);else if(v instanceof Set)edit.putStringSet(item.getKey(),new HashSet<String>((Set<String>)v));}if(keepScan&&!measuredStations.isEmpty())edit.putString("stations",measuredStations);edit.commit();}
        finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);
    }
}
